/* 解析命令行参数（沿用 vg* 工具风格，getopt） */

static int parse_args(int argc, FAR char *argv[],
                      FAR struct vgmqtt_cfg_s *cfg)
{
  int opt;

  memset(cfg, 0, sizeof(*cfg));
  cfg->port   = VGMQTT_DEFAULT_PORT;
  cfg->topic  = VGMQTT_TOPIC;
  cfg->qos    = 0;
  cfg->retain = true;
  cfg->wait_secs = 0;

  while ((opt = getopt(argc, argv, "h:p:u:P:t:m:q:r:w:")) != ERROR)
    {
      switch (opt)
        {
          case 'h':
            cfg->host = optarg;
            break;

          case 'p':
            cfg->port = optarg;
            break;

          case 'u':
            cfg->user = optarg;
            break;

          case 'P':
            cfg->pass = optarg;
            break;

          case 't':
            cfg->topic = optarg;
            break;

          case 'm':
            cfg->msg = optarg;
            break;

          case 'q':
            cfg->qos = (uint8_t)strtol(optarg, NULL, 10);
            break;

          case 'r':
            cfg->retain = true;
            break;

          case 'w':
            cfg->wait_secs = atoi(optarg);
            break;

          default:
            show_usage(argv[0]);
            return ERROR;
        }
    }

